-- Catálogo de 185 escenarios de incidentes por giro de negocio (28 verticales +
-- "Universal"), aportado por el usuario. Mucho más específico que
-- public.solution_playbook (que solo cubre 23 categorías genéricas): aquí cada
-- fila es un escenario concreto (ej. "alimento crudo, objeto extraño o alérgeno
-- no informado" en restaurantes) con su propia urgencia, señales de texto para
-- detectarlo en el comentario libre del cliente, y guía operativa completa —
-- incluyendo qué NO hacer y cuándo escalar, clave para casos críticos (acoso,
-- seguridad, salud). generateCaseAiSuggestion() en lib/cases.ts intenta esta
-- tabla primero (findIncidentMatch, por señales de texto); si no hay coincidencia
-- cae a public.solution_playbook (por categoría) y luego a IA.

create table public.incident_playbook (
  id uuid primary key default gen_random_uuid(),
  scenario_id text not null unique,
  vertical text not null,
  category_label text not null,
  problem text not null,
  urgency_default urgency_level not null,
  signals text[] not null default '{}',
  questions_to_confirm text[] not null default '{}',
  immediate_action text not null,
  owner_role text not null,
  customer_response text not null,
  root_cause_action text not null,
  ack_sla text,
  action_sla text,
  resolution_target text,
  escalation text,
  do_not text[] not null default '{}',
  evidence text[] not null default '{}',
  success_metrics text[] not null default '{}',
  confidence_rule text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index incident_playbook_vertical_idx on public.incident_playbook (vertical);
create index incident_playbook_urgency_idx on public.incident_playbook (urgency_default);
create index incident_playbook_signals_gin_idx on public.incident_playbook using gin (signals);

alter table public.incident_playbook enable row level security;

-- Contenido de referencia compartido, sin datos sensibles — lectura abierta a
-- cualquier usuario autenticado, igual que solution_playbook y feedback_categories.
create policy "incident_playbook_select" on public.incident_playbook
  for select to authenticated using (true);

create policy "incident_playbook_write_superadmin" on public.incident_playbook
  for all using (public.is_superadmin())
  with check (public.is_superadmin());

insert into public.incident_playbook
  (scenario_id, vertical, category_label, problem, urgency_default, signals,
   questions_to_confirm, immediate_action, owner_role, customer_response,
   root_cause_action, ack_sla, action_sla, resolution_target, escalation, do_not,
   evidence, success_metrics, confidence_rule)
values
  ('SEG-01', 'Universal', 'Seguridad', 'Amenaza, agresión, arma o violencia', 'critical', ARRAY['amenaza, agresión, arma o violencia']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Separar a las personas, proteger al afectado, llamar al 911 cuando proceda y preservar evidencia.', 'Gerencia + seguridad + emergencias', 'Estamos priorizando tu seguridad. El responsable del establecimiento ya fue alertado y tomará control inmediato. Si estás en peligro, aléjate y llama al 911.', 'Activar protocolo de violencia; no confrontar ni investigar públicamente.', '0–5 min', 'Inmediata', 'Contención en 15 min; investigación formal', 'Escalar siempre; no pedir detalles sensibles por chat.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Tiempo de contención y ausencia de nuevas exposiciones.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('SAL-01', 'Universal', 'Salud y seguridad', 'Posible intoxicación, reacción grave o emergencia médica', 'critical', ARRAY['posible intoxicación, reacción grave o emergencia médica']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Indicar atención médica/911, detener temporalmente el producto o servicio implicado y aislar lote/equipo.', 'Gerencia + responsable sanitario', 'Lamentamos lo ocurrido. Tu salud es la prioridad: busca atención médica inmediata o llama al 911 si hay síntomas graves. Ya escalamos el caso para contención e investigación.', 'Trazabilidad, revisión sanitaria, documentación y notificación a autoridad cuando corresponda.', '0–5 min', 'Inmediata', 'Contención en 15 min; investigación formal', 'No diagnosticar, medicar ni admitir causalidad sin investigación.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Contención del lote/equipo y cierre documentado.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('FUE-01', 'Universal', 'Instalaciones', 'Humo, incendio, fuga de gas, olor químico o riesgo eléctrico', 'critical', ARRAY['humo, incendio, fuga de gas, olor químico o riesgo eléctrico']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Evacuar, cortar operación si es seguro, llamar a emergencias y evitar reingreso.', 'Gerencia + seguridad + mantenimiento', 'Gracias por reportarlo. Hemos activado el protocolo de emergencia. Aléjate del área y sigue las indicaciones del personal o de emergencias.', 'Inspección certificada y reapertura autorizada.', '0–5 min', 'Inmediata', 'Contención en 15 min; investigación formal', 'Escalar siempre; bloquear respuestas promocionales.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Evacuación y validación de reapertura.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('ACO-01', 'Universal', 'Conducta', 'Acoso, discriminación o conducta sexual inapropiada', 'critical', ARRAY['acoso, discriminación o conducta sexual inapropiada']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Proteger y separar al afectado del presunto responsable; ofrecer canal privado y conservar registros.', 'Gerencia + RR. HH. + legal', 'Gracias por informarlo. Tomamos esto con máxima seriedad. Queremos proteger tu privacidad y escalarlo de inmediato con el equipo responsable.', 'Investigación imparcial, no represalias y medidas laborales conforme a política y ley.', '0–5 min', 'Inmediata', 'Contención en 15 min; investigación formal', 'No confrontar, culpar ni pedir relato público; evitar prometer resultado.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Primera protección, investigación y seguimiento seguro.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('DAT-01', 'Universal', 'Privacidad', 'Exposición de datos personales o credenciales', 'critical', ARRAY['exposición de datos personales o credenciales']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Revocar accesos, contener exposición, preservar logs y avisar al responsable de privacidad.', 'Seguridad de información + legal', 'Gracias por alertarnos. Hemos escalado el incidente al equipo de privacidad para contenerlo y verificar el alcance. No compartas más datos por este canal.', 'Evaluación de impacto, notificaciones aplicables, corrección técnica y auditoría.', '0–5 min', 'Inmediata', 'Contención en 15 min; investigación formal', 'Nunca solicitar contraseñas, tarjetas completas o expedientes sensibles.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Tiempo de contención y usuarios protegidos.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('FRA-01', 'Universal', 'Finanzas y seguridad', 'Fraude, robo, extorsión o manipulación de pago', 'critical', ARRAY['fraude, robo, extorsión o manipulación de pago']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Detener transacción si es seguro, resguardar evidencia y orientar al canal bancario/autoridad.', 'Gerencia + prevención de pérdidas + legal', 'Hemos escalado el reporte con prioridad máxima. No compartas NIP, CVV ni contraseñas. Si existe riesgo inmediato, contacta a tu banco y a las autoridades.', 'Conciliación, investigación y controles antifraude.', '0–5 min', 'Inmediata', 'Contención en 15 min; investigación formal', 'No acusar públicamente a una persona sin evidencia.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Fondos protegidos y caso trazable.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('PER-01', 'Universal', 'Personal', 'Empleado grosero, intimidante o que se niega a ayudar', 'high', ARRAY['empleado grosero, intimidante o que se niega a ayudar']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Retirar al colaborador de la interacción, asignar otro responsable y escuchar al cliente.', 'Supervisor de turno + RR. HH.', 'Lamentamos la forma en que fuiste atendido. Un supervisor revisará el caso y dará continuidad de manera privada.', 'Revisar evidencia, coaching o medida disciplinaria proporcional y seguimiento.', '≤15 min', '≤30 min', '≤4 h o antes de que termine el turno', 'Subir a U1 si hay amenazas, acoso o discriminación.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Recuperación del cliente y no recurrencia.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('COB-01', 'Universal', 'Pagos', 'Cobro duplicado, monto distinto o cargo no reconocido', 'high', ARRAY['cobro duplicado, monto distinto o cargo no reconocido']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Verificar ticket y terminal, detener cobros adicionales y abrir conciliación.', 'Caja + gerente + finanzas', 'Gracias por reportarlo. Revisaremos la operación con prioridad. Por seguridad, comparte solo folio, fecha y monto; nunca datos completos de tu tarjeta.', 'Reembolso o aclaración documentada según resultado.', '≤15 min', '≤30 min', '≤4 h o antes de que termine el turno', 'U1 si hay patrón de fraude; no prometer fecha bancaria exacta.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Conciliación y devolución confirmada.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('ACC-01', 'Universal', 'Instalaciones', 'Accidente por piso, mobiliario o instalación', 'high', ARRAY['accidente por piso, mobiliario o instalación']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Atender al afectado, acordonar el área, documentar y corregir el peligro.', 'Gerencia + seguridad + mantenimiento', 'Sentimos lo ocurrido. El equipo responsable atenderá el área y dará seguimiento inmediato. Si requieres atención médica, solicítala de inmediato.', 'Inspección de causa, mantenimiento y reporte de incidente.', '≤15 min', '≤30 min', '≤4 h o antes de que termine el turno', 'U1 si hay lesión grave o riesgo activo generalizado.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Riesgo eliminado y seguimiento al afectado.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('HIG-01', 'Universal', 'Higiene', 'Suciedad severa, plaga o condición insalubre', 'high', ARRAY['suciedad severa, plaga o condición insalubre']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Cerrar o aislar el área/producto, limpiar y verificar antes de reabrir.', 'Gerencia + limpieza + calidad', 'Gracias por avisarnos. Hemos escalado el reporte para inspección y corrección inmediata del área.', 'Control de plagas, auditoría de rutinas y evidencia de corrección.', '≤15 min', '≤30 min', '≤4 h o antes de que termine el turno', 'U1 si implica alimentos, agujas, sangre, químicos o peligro de salud.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Área liberada tras verificación.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('SER-01', 'Universal', 'Operación', 'Servicio o producto principal no funciona', 'medium', ARRAY['servicio o producto principal no funciona']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Confirmar falla, ofrecer alternativa realista y comunicar plazo.', 'Supervisor + operación', 'Lamentamos que el servicio no cumpliera. Ya registramos el caso y un responsable revisará la mejor alternativa disponible.', 'Análisis de causa y ajuste de proceso/proveedor.', '≤2 h', 'Mismo turno', '≤24 h', 'U2 si afecta a muchos clientes o bloquea un servicio esencial.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Restablecimiento y recuperación.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('DEM-01', 'Universal', 'Tiempos', 'Espera excesiva o fila sin información', 'medium', ARRAY['espera excesiva o fila sin información']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Informar tiempo real, priorizar vulnerables y ofrecer reprogramación o alternativa.', 'Supervisor de turno', 'Gracias por tu paciencia. Reconocemos la demora y estamos revisando tu caso para darte un tiempo real y una alternativa.', 'Ajustar dotación, agenda, capacidad y alertas de saturación.', '≤2 h', 'Mismo turno', '≤24 h', 'U2 si hay pacientes, pasajeros o seguridad comprometida.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Tiempo de espera y abandono.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('COM-01', 'Universal', 'Comunicación', 'Información contradictoria o promesa incumplida', 'medium', ARRAY['información contradictoria o promesa incumplida']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Confirmar lo ofrecido y dar una única versión autorizada.', 'Supervisor + área comercial', 'Entendemos la confusión. Verificaremos lo ofrecido y te responderemos con una solución clara por el canal acordado.', 'Centralizar políticas, capacitar y registrar compromisos.', '≤2 h', 'Mismo turno', '≤24 h', 'U2 si involucra dinero significativo, salud o contrato.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Resolución en primer contacto.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('CAL-01', 'Universal', 'Calidad', 'Calidad inferior, resultado deficiente o producto dañado', 'medium', ARRAY['calidad inferior, resultado deficiente o producto dañado']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Inspeccionar, retirar unidad/servicio y aplicar política de reposición o corrección.', 'Calidad + supervisor', 'Lamentamos que la calidad no fuera la esperada. Revisaremos el caso y te propondremos una corrección conforme a la política aplicable.', 'Trazabilidad, proveedor, checklist y muestreo.', '≤2 h', 'Mismo turno', '≤24 h', 'U2 si puede causar daño.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Reposición/corrección y recurrencia.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('RUI-01', 'Universal', 'Ambiente', 'Ruido, temperatura, olor o comodidad', 'low', ARRAY['ruido, temperatura, olor o comodidad']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Ajustar si es posible y ofrecer cambio de zona.', 'Operación + mantenimiento', 'Gracias por señalarlo. Revisaremos el ambiente del área y haremos el ajuste posible para mejorar tu experiencia.', 'Revisar climatización, horarios y mantenimiento preventivo.', '≤8 h', '≤48 h', '≤5 días', 'U2/U1 si el olor sugiere gas, humo o químico.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Quejas ambientales por zona.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('INF-01', 'Universal', 'Accesibilidad', 'Señalización, accesibilidad o indicaciones deficientes', 'medium', ARRAY['señalización, accesibilidad o indicaciones deficientes']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Acompañar al cliente y retirar barreras temporales.', 'Operación + instalaciones', 'Gracias por informarnos. Te ayudaremos de inmediato y revisaremos la barrera para evitar que vuelva a afectar a otras personas.', 'Auditoría WCAG/física, señalización y rutas accesibles.', '≤2 h', 'Mismo turno', '≤24 h', 'U2 si bloquea evacuación o atención esencial.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Barreras corregidas.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('SUG-01', 'Universal', 'Mejora', 'Sugerencia o preferencia sin incidente', 'low', ARRAY['sugerencia o preferencia sin incidente']::text[], ARRAY['¿La situación continúa?','¿Existe riesgo o lesión?','¿Dónde y cuándo ocurrió?']::text[], 'Agradecer, categorizar y evitar prometer implementación.', 'Experiencia del cliente', 'Gracias por la sugerencia. La registramos para que el equipo responsable la considere en su revisión de mejoras.', 'Agrupar tendencias y priorizar por impacto/esfuerzo.', '≤8 h', '≤48 h', '≤5 días', 'Elevar si la sugerencia revela un riesgo oculto.', ARRAY['No minimizar.','No pedir información sensible públicamente.','No asegurar culpabilidad o causalidad antes de investigar.']::text[], ARRAY['fecha/hora','ubicación','folio','registros operativos','evidencia con consentimiento']::text[], ARRAY['Adopción y volumen de menciones.']::text[], 'Mostrar evidencia, periodo, número de respuestas y confianza.'),
  ('V01-01', 'Restaurantes y comida rápida', 'Seguridad alimentaria', 'Alimento crudo, objeto extraño o alérgeno no informado', 'critical', ARRAY['alimento crudo, objeto extraño o alérgeno no informado']::text[], ARRAY['¿La situación sigue ocurriendo ahora?','¿Hay alguna persona lesionada o en riesgo?','¿Cuándo y en qué área/sucursal ocurrió?']::text[], 'Retirar platillo y lote; atender al cliente y detener su venta.', 'Chef + gerente + calidad', 'Lamentamos lo ocurrido. Registramos tu reporte sobre alimento crudo, objeto extraño o alérgeno no informado y lo escalamos con prioridad U1. Un responsable dará seguimiento por un canal privado.', 'Auditar proveedor, separación, temperaturas y comunicación de alérgenos.', '0–5 min', 'Inmediata', 'Contención en 15 min; investigación formal', 'Escalar a U1 si existe peligro actual, lesión, menor involucrado, violencia, delito, exposición de datos o múltiples reportes coincidentes.', ARRAY['No culpar al cliente.','No prometer compensación o resultado sin autorización.','No solicitar datos sensibles en texto libre.']::text[], ARRAY['fecha y hora','sucursal/área','folio o reserva','evidencia disponible con consentimiento']::text[], ARRAY['tiempo de primera respuesta','tiempo de contención','reincidencia a 7/30 días','confirmación de cierre']::text[], 'No emitir recomendación definitiva con menos de 3 casos comparables; mostrar tamaño de muestra y periodo.'),
